store = []

def maybe_write(user_id, turn_id, text):
    lowered = text.lower()
    if "remember" in lowered and "prefer" in lowered:
        value = text.split("remember", 1)[1].strip(" :.")
        store.append({"ns": ("user", user_id), "type": "preference", "value": value, "source": turn_id, "status": "active"})

def recall(user_id, task):
    if "example" not in task.lower() and "lesson" not in task.lower():
        return []
    return [m for m in store if m["ns"] == ("user", user_id) and m["status"] == "active"]

maybe_write("u1", "turn-7", "Please remember: I prefer TypeScript examples.")
print(recall("u1", "write a lesson with examples"))
print(recall("u1", "check my invoice"))
